mapper.select:
SELECT

FROM tariff_source_config s
WHERE 1 = 1

  AND s.province_code = #{req.provinceCode}


  AND s.source_type = #{req.sourceType}


  AND s.source_name LIKE CONCAT('%', #{req.sourceName}, '%')


  AND s.enabled = #{req.enabled}

ORDER BY s.enabled DESC, s.province_code, s.source_type, s.id DESC

SELECT

FROM tariff_source_document d
WHERE 1 = 1

  AND d.year_month = #{req.yearMonth}


  AND d.version = #{req.version}


  AND d.province_code = #{req.provinceCode}


  AND d.source_type = #{req.sourceType}


  AND d.status = #{req.status}


  AND d.batch_no = #{req.batchNo}


  AND d.source_name LIKE CONCAT('%', #{req.sourceName}, '%')

ORDER BY d.publish_time DESC, d.update_time DESC, d.id DESC
